tasks.reference:
def product_of_positives(numbers):
    result = 1
    for x in numbers:
        if x > 0:
            result *= x
    return result

def shortest_word_last(text):
    best = None
    for w in text.split():
        if best is None or len(w) <= len(best):
            best = w
    return best

def remove_first(items, value):
    result = list(items)
    if value in result:
        result.remove(value)
    return result

