def shared_values(a, b):
    result = []
    i = j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    return result + a[i:] + b[j:]

def partial_sums(numbers):
    result = []
    best = None
    for x in numbers:
        if best is None or x > best:
            best = x
        result.append(best)
    return result
